import os
import torch


class Config:
    """
    Centralized configuration for the Deep Cross Network (DCNv2) pipeline.
    """

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # File Paths
    # ==========================================
    # Input metadata paths (generated by the provided script)
    TRAIN_PATH = "./metadata/train.csv"
    VAL_PATH = "./metadata/val.csv"
    TEST_PATH = "./metadata/test.csv"
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output directories and paths
    WORKING_DIR = "./working/idea_2"
    SUBMISSION_DIR = "./submission"

    # Cache files for processed data (parquet format)
    # Updated to v2 to invalidate stale cache (Cite debug_lesson_1)
    TRAIN_PROCESSED_PATH = os.path.join(WORKING_DIR, "train_processed_v2.parquet")
    VAL_PROCESSED_PATH = os.path.join(WORKING_DIR, "val_processed_v2.parquet")
    TEST_PROCESSED_PATH = os.path.join(WORKING_DIR, "test_processed_v2.parquet")

    # Model artifacts
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Configuration
    # ==========================================
    ID_COL = "id"
    TARGET_COL = "target"
    CATEGORICAL_COL = "f_27"
    DISCRETE_COLS = ["f_29", "f_30"]

    # Continuous features: f_00 to f_30, excluding f_27 and discrete cols
    # We also append the engineered feature 'unique_character_count' later in the pipeline
    BASE_CONT_COLS = [f"f_{i:02d}" for i in range(31) if i not in [27, 29, 30]]

    # Character Embedding Config
    STR_LEN = 10  # Length of the string in f_27
    VOCAB_SIZE = 28  # 26 letters (A-Z) + 1 padding/unknown + 1 buffer

    # ==========================================
    # Model Architecture (DCNv2 + Funnel MLP)
    # ==========================================
    EMBEDDING_DIM = 8  # Dimension for character embeddings
    NUM_CROSS_LAYERS = 3  # Number of layers in the Cross Network branch
    HIDDEN_LAYERS = [512, 256, 128]  # Funnel architecture for Deep branch
    DROPOUT = 0.1  # Dropout rate for the Deep branch

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    BATCH_SIZE = 2048
    EPOCHS = 30
    LEARNING_RATE = 1e-2  # Max LR for OneCycleLR
    WEIGHT_DECAY = 1e-5  # L2 Regularization
    PATIENCE = 5  # Early stopping patience

    # ==========================================
    # Hardware & Execution
    # ==========================================
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def create_dirs(cls):
        """Creates necessary output directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
